import{_ as n,C as p,o as l,c as m,j as a,a as e,E as i,a2 as r}from"./chunks/framework.B-bxTAy7.js";const b=JSON.parse('{"title":"12 · 低功耗与综合项目","description":"","frontmatter":{"title":"12 · 低功耗与综合项目"},"headers":[],"relativePath":"embedded/lowpower-project.md","filePath":"embedded/lowpower-project.md","lastUpdated":1792416913000}'),c={name:"embedded/lowpower-project.md"};function o(h,s,g,d,y,u){const t=p("Meta");return l(),m("div",null,[s[0]||(s[0]=a("h1",{id:"_12-·-低功耗与综合项目",tabindex:"-1"},[e("12 · 低功耗与综合项目 "),a("a",{class:"header-anchor",href:"#_12-·-低功耗与综合项目","aria-label":'Permalink to "12 · 低功耗与综合项目"'},"​")],-1)),i(t,{time:"40 min",level:"核心",note:"让电池用上一年而不是一天；再用一个贯通项目把十二章串起来"}),s[1]||(s[1]=r(`<h2 id="结论先行" tabindex="-1">结论先行 <a class="header-anchor" href="#结论先行" aria-label="Permalink to &quot;结论先行&quot;">​</a></h2><ol><li><strong>低功耗的第一原则是「多睡」</strong>：不是「跑得慢一点」，而是<strong>让芯片绝大部分时间处于最深的睡眠模式</strong>，只在必要时刻醒来干活。</li><li><strong>三种低功耗模式</strong>：<strong>Sleep</strong>（只停 CPU，外设还在跑，唤醒最快）、<strong>Stop</strong>（停几乎所有时钟，保留 RAM 与寄存器，µA 级）、<strong>Standby</strong>（最低功耗，RAM 掉电，唤醒等于复位）。</li><li><strong>功耗预算要算占空比</strong>：平均电流 = 活跃电流 × 活跃占比 + 睡眠电流 × 睡眠占比。<strong>活跃时间哪怕只占 0.1%，往往也主导了平均电流</strong>。</li><li><strong>看门狗是产品可靠性的最后防线</strong>：程序跑飞/死循环时自动复位。<strong>独立看门狗（IWDG）一旦开启就停不下来</strong>（除非复位），必须在主循环里定期喂狗。</li><li><strong>综合项目的价值在于「取舍」</strong>：真实项目不会把所有资源都占满，而是在速度、精度、功耗、成本之间做权衡——这才是工程能力。</li></ol><h2 id="一、三种低功耗模式" tabindex="-1">一、三种低功耗模式 <a class="header-anchor" href="#一、三种低功耗模式" aria-label="Permalink to &quot;一、三种低功耗模式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>停了什么</th><th>保留什么</th><th>典型电流（F1/F4）</th><th>唤醒后</th></tr></thead><tbody><tr><td><strong>Sleep</strong></td><td>仅 CPU 时钟</td><td>所有外设、RAM、寄存器</td><td>几 mA ~ 十几 mA</td><td>从原处继续执行</td></tr><tr><td><strong>Stop</strong></td><td>所有时钟（除少数）</td><td><strong>RAM 内容、寄存器、IO 状态</strong></td><td><strong>几十 µA</strong></td><td>从原处继续（需重新配时钟）</td></tr><tr><td><strong>Standby</strong></td><td>整个 1.8 V 域断电</td><td>仅备份寄存器 + RTC</td><td><strong>几 µA</strong></td><td><strong>相当于复位重启</strong></td></tr></tbody></table><p><strong>选哪个</strong>：</p><ul><li>需要<strong>快速响应</strong>、且外设要持续工作（如 UART 接收）→ Sleep；</li><li>大部分时间在等、但要<strong>保留运行状态</strong>（最常见）→ <strong>Stop</strong>（性价比最高）；</li><li>超长待机、唤醒后反正要重新初始化 → Standby。</li></ul><p><strong>唤醒源</strong>：</p><ul><li><strong>Stop</strong>：任意外部中断（EXTI）、RTC 闹钟、USB 唤醒等；</li><li><strong>Standby</strong>：WKUP 引脚上升沿、RTC 闹钟、NRST 外部复位、看门狗。</li></ul><div class="tip custom-block"><p class="custom-block-title">例 1 · 停止模式能撑多久</p><p>用一颗 <strong>200 mAh</strong> 的电池（CR2032 纽扣电池约 220 mAh），假设系统大部分时间在 Stop 模式，电流 <strong>20 µA</strong>：</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>续航</mtext><mo>=</mo><mfrac><mrow><mn>200</mn><mtext> mAh</mtext></mrow><mrow><mn>0.02</mn><mtext> mA</mtext></mrow></mfrac><mo>=</mo><mn>10000</mn><mtext> h</mtext><mo>≈</mo><mn>417</mn><mtext> 天</mtext><mo>≈</mo><mn>1.14</mn><mtext> 年</mtext></mrow><annotation encoding="application/x-tex">\\text{续航} = \\frac{200\\ \\text{mAh}}{0.02\\ \\text{mA}} = 10000\\ \\text{h} \\approx 417\\ \\text{天} \\approx 1.14\\ \\text{年} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord cjk_fallback">续航</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.0574em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3714em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">0.02</span><span class="mspace"> </span><span class="mord text"><span class="mord">mA</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">200</span><span class="mspace"> </span><span class="mord text"><span class="mord">mAh</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord">10000</span><span class="mspace"> </span><span class="mord text"><span class="mord">h</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">417</span><span class="mspace"> </span><span class="mord text"><span class="mord cjk_fallback">天</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">1.14</span><span class="mspace"> </span><span class="mord text"><span class="mord cjk_fallback">年</span></span></span></span></span></span><p>对比其他模式：</p><table tabindex="0"><thead><tr><th>模式</th><th>电流</th><th>200 mAh 续航</th></tr></thead><tbody><tr><td>运行 @72 MHz</td><td>30 mA</td><td><strong>6.7 小时</strong></td></tr><tr><td>Sleep</td><td>10 mA</td><td>20 小时</td></tr><tr><td><strong>Stop</strong></td><td><strong>20 µA</strong></td><td><strong>417 天</strong></td></tr><tr><td>Standby</td><td>2 µA</td><td>11.4 年</td></tr></tbody></table><p><strong>结论</strong>：从「运行」切到「Stop」，续航从几个小时变成一年多——<strong>差了三个数量级</strong>。这就是为什么低功耗设计的第一优先级是「让它睡着」，而不是优化那点运算效率。</p><p>（以上电流为数量级参考，实际必须查所用型号数据手册的对应表格。）</p></div><h2 id="二、算功耗预算-占空比决定一切" tabindex="-1">二、算功耗预算：占空比决定一切 <a class="header-anchor" href="#二、算功耗预算-占空比决定一切" aria-label="Permalink to &quot;二、算功耗预算：占空比决定一切&quot;">​</a></h2><p>真实产品不是一直睡，而是「周期性醒来干活」。平均电流由占空比决定：</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mi>I</mi><mrow><mi>a</mi><mi>v</mi><mi>g</mi></mrow></msub><mo>=</mo><msub><mi>I</mi><mrow><mi>a</mi><mi>c</mi><mi>t</mi><mi>i</mi><mi>v</mi><mi>e</mi></mrow></msub><mo>×</mo><mfrac><msub><mi>t</mi><mrow><mi>a</mi><mi>c</mi><mi>t</mi><mi>i</mi><mi>v</mi><mi>e</mi></mrow></msub><mi>T</mi></mfrac><mo>+</mo><msub><mi>I</mi><mrow><mi>s</mi><mi>l</mi><mi>e</mi><mi>e</mi><mi>p</mi></mrow></msub><mo>×</mo><mfrac><msub><mi>t</mi><mrow><mi>s</mi><mi>l</mi><mi>e</mi><mi>e</mi><mi>p</mi></mrow></msub><mi>T</mi></mfrac></mrow><annotation encoding="application/x-tex">I_{avg} = I_{active} \\times \\frac{t_{active}}{T} + I_{sleep} \\times \\frac{t_{sleep}}{T} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">a</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">g</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">a</span><span class="mord mathnormal mtight">c</span><span class="mord mathnormal mtight">t</span><span class="mord mathnormal mtight">i</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span><span class="mord mathnormal mtight">e</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.9781em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.2921em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">a</span><span class="mord mathnormal mtight">c</span><span class="mord mathnormal mtight">t</span><span class="mord mathnormal mtight">i</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span><span class="mord mathnormal mtight">e</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">s</span><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span><span class="mord mathnormal mtight">ee</span><span class="mord mathnormal mtight">p</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.9781em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.2921em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">s</span><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span><span class="mord mathnormal mtight">ee</span><span class="mord mathnormal mtight">p</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span><div class="tip custom-block"><p class="custom-block-title">例 2 · 每秒唤醒采集一次，平均电流多少</p><p>系统每秒唤醒一次，活跃 <strong>1 ms @30 mA</strong>（采集 + 发送），其余 <strong>999 ms</strong> 在 Stop 模式 @20 µA：</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mi>I</mi><mrow><mi>a</mi><mi>v</mi><mi>g</mi></mrow></msub><mo>=</mo><mn>30</mn><mo>×</mo><mfrac><mn>1</mn><mn>1000</mn></mfrac><mo>+</mo><mn>0.02</mn><mo>×</mo><mfrac><mn>999</mn><mn>1000</mn></mfrac><mo>=</mo><mn>0.030</mn><mo>+</mo><mn>0.01998</mn><mo>≈</mo><mn>0.050</mn><mtext> mA</mtext><mo>=</mo><mn>50</mn><mtext> </mtext><mi>μ</mi><mtext>A</mtext></mrow><annotation encoding="application/x-tex">I_{avg} = 30 \\times \\frac{1}{1000} + 0.02 \\times \\frac{999}{1000} = 0.030 + 0.01998 \\approx 0.050\\ \\text{mA} = 50\\ \\mu\\text{A} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">a</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">g</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">30</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:2.0074em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1000</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">0.02</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:2.0074em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1000</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">999</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">0.030</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.01998</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">0.050</span><span class="mspace"> </span><span class="mord text"><span class="mord">mA</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord">50</span><span class="mspace"> </span><span class="mord mathnormal">μ</span><span class="mord text"><span class="mord">A</span></span></span></span></span></span><p>续航：</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mfrac><mrow><mn>200</mn><mtext> mAh</mtext></mrow><mrow><mn>0.05</mn><mtext> mA</mtext></mrow></mfrac><mo>=</mo><mn>4000</mn><mtext> h</mtext><mo>≈</mo><mn>167</mn><mtext> 天</mtext></mrow><annotation encoding="application/x-tex">\\frac{200\\ \\text{mAh}}{0.05\\ \\text{mA}} = 4000\\ \\text{h} \\approx 167\\ \\text{天} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:2.0574em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3714em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">0.05</span><span class="mspace"> </span><span class="mord text"><span class="mord">mA</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">200</span><span class="mspace"> </span><span class="mord text"><span class="mord">mAh</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord">4000</span><span class="mspace"> </span><span class="mord text"><span class="mord">h</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">167</span><span class="mspace"> </span><span class="mord text"><span class="mord cjk_fallback">天</span></span></span></span></span></span><p><strong>对比一直运行</strong>（6.7 小时），改善约 <strong>600 倍</strong>。</p><p><strong>关键洞察</strong>：虽然活跃只占 0.1% 的时间，但活跃电流（30 mA）是睡眠电流（20 µA）的 1500 倍，所以<strong>活跃部分贡献了平均电流的 60%</strong>（0.030 中的 0.030 vs 0.020）。</p><p><strong>所以优化顺序是</strong>：① <strong>缩短活跃时间</strong>（比降电流更有效）→ ② 降低活跃时的电流（降频、关外设）→ ③ 降低睡眠电流（选更深模式）。</p></div><div class="tip custom-block"><p class="custom-block-title">例 3 · 唤醒频率对续航的影响</p><p>同样是「唤醒 1 ms @30 mA、其余 Stop @20 µA」，只改变唤醒间隔：</p><table tabindex="0"><thead><tr><th>唤醒间隔</th><th>占空比</th><th>平均电流</th><th>200 mAh 续航</th></tr></thead><tbody><tr><td>每 1 秒</td><td>0.1%</td><td>50 µA</td><td>167 天</td></tr><tr><td>每 10 秒</td><td>0.01%</td><td>23 µA</td><td><strong>362 天</strong></td></tr><tr><td>每 60 秒</td><td>0.0017%</td><td>20.5 µA</td><td>407 天</td></tr></tbody></table><p><strong>边际效益递减</strong>：从 1 秒改到 10 秒，续航翻倍；从 10 秒改到 60 秒，只多 45 天——因为此时平均电流已经逼近睡眠电流的下限（20 µA），再怎么少干活也降不下去。</p><p><strong>工程结论</strong>：</p><ol><li>唤醒间隔从 1 秒放宽到 10 秒，收益最大（续航翻倍且多数应用可接受）；</li><li>一旦平均电流接近睡眠电流，<strong>继续拉长间隔已无意义</strong>，此时该换更低功耗的硬件或更深的睡眠模式；</li><li><strong>唤醒本身也有开销</strong>：从 Stop 唤醒后要重新初始化时钟、外设，这些时间也要算进活跃时间。频繁唤醒（如每 10 ms 一次）反而可能比一直运行更耗电。</li></ol></div><h2 id="三、降低功耗的工程手段" tabindex="-1">三、降低功耗的工程手段 <a class="header-anchor" href="#三、降低功耗的工程手段" aria-label="Permalink to &quot;三、降低功耗的工程手段&quot;">​</a></h2><table tabindex="0"><thead><tr><th>手段</th><th>效果</th><th>说明</th></tr></thead><tbody><tr><td><strong>关掉不用的外设时钟</strong></td><td>显著</td><td><code>__HAL_RCC_xxx_CLK_DISABLE()</code>，最基本也最有效</td></tr><tr><td><strong>降低主频</strong></td><td>显著</td><td>功耗近似与频率成正比；能用 8 MHz 就别跑 72 MHz</td></tr><tr><td><strong>进入 Stop/Standby</strong></td><td>极大</td><td>见上文</td></tr><tr><td><strong>IO 口配置</strong></td><td>中等</td><td><strong>悬空的输入引脚会漏电</strong>：不用的引脚配成模拟输入（功耗最低）或输出固定电平</td></tr><tr><td><strong>关闭 ADC/模拟模块</strong></td><td>中等</td><td>模拟部分电流不小，不用时关掉</td></tr><tr><td><strong>外设用 DMA</strong></td><td>中等</td><td>CPU 可以更早进入睡眠</td></tr><tr><td><strong>缩短活跃时间</strong></td><td><strong>最大</strong></td><td>见例 2——这是收益最高的一招</td></tr></tbody></table><p><strong>一个常被忽略的坑</strong>：未使用的 GPIO 若保持<strong>浮空输入</strong>状态，引脚电平可能落在中间区域，导致输入缓冲器持续导通而<strong>消耗可观的电流</strong>（可达数百 µA，直接吃掉 Stop 模式的省电效果）。正确做法是<strong>把不用的引脚配成模拟输入</strong>（断开数字输入缓冲）或输出固定电平。</p><h2 id="四、看门狗" tabindex="-1">四、看门狗 <a class="header-anchor" href="#四、看门狗" aria-label="Permalink to &quot;四、看门狗&quot;">​</a></h2><p>看门狗是一个独立定时器：<strong>如果不按时「喂狗」（重置计数器），它就会复位整个芯片</strong>。用来在程序跑飞、死循环、硬件异常时自动恢复。</p><table tabindex="0"><thead><tr><th>类型</th><th>时钟</th><th>特点</th></tr></thead><tbody><tr><td><strong>IWDG</strong> 独立看门狗</td><td>内部 LSI（约 40 kHz，独立于主时钟）</td><td><strong>一旦启动无法停止</strong>（除非复位）；即使主时钟挂了也能工作</td></tr><tr><td><strong>WWDG</strong> 窗口看门狗</td><td>PCLK</td><td>必须在<strong>时间窗口内</strong>喂狗：太早喂也算错误（可检测程序跑乱节奏）</td></tr></tbody></table><p><strong>超时时间计算</strong>（IWDG）：</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mi>T</mi><mrow><mi>o</mi><mi>u</mi><mi>t</mi></mrow></msub><mo>=</mo><mfrac><mrow><mtext>预分频系数</mtext><mo>×</mo><mo stretchy="false">(</mo><mtext>重装载值</mtext><mo>+</mo><mn>1</mn><mo stretchy="false">)</mo></mrow><msub><mi>f</mi><mrow><mi>L</mi><mi>S</mi><mi>I</mi></mrow></msub></mfrac></mrow><annotation encoding="application/x-tex">T_{out} = \\frac{\\text{预分频系数} \\times (\\text{重装载值} + 1)}{f_{LSI}} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">o</span><span class="mord mathnormal mtight">u</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.3074em;vertical-align:-0.8804em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.427em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">L</span><span class="mord mathnormal mtight" style="margin-right:0.0576em;">S</span><span class="mord mathnormal mtight" style="margin-right:0.0785em;">I</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord text"><span class="mord cjk_fallback">预分频系数</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mopen">(</span><span class="mord text"><span class="mord cjk_fallback">重装载值</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord">1</span><span class="mclose">)</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.8804em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span><div class="tip custom-block"><p class="custom-block-title">例 4 · 配一个 1 秒超时的独立看门狗</p><p>LSI ≈ 40 kHz，取预分频 <strong>64</strong>、重装载 <strong>624</strong>：</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mi>f</mi><mrow><mi>c</mi><mi>n</mi><mi>t</mi></mrow></msub><mo>=</mo><mfrac><mn>40000</mn><mn>64</mn></mfrac><mo>=</mo><mn>625</mn><mtext> Hz</mtext><mo separator="true">,</mo><mspace width="2em"></mspace><msub><mi>T</mi><mrow><mi>o</mi><mi>u</mi><mi>t</mi></mrow></msub><mo>=</mo><mfrac><mrow><mn>624</mn><mo>+</mo><mn>1</mn></mrow><mn>625</mn></mfrac><mo>=</mo><mn>1.0</mn><mtext> s</mtext></mrow><annotation encoding="application/x-tex">f_{cnt} = \\frac{40000}{64} = 625\\ \\text{Hz},\\qquad T_{out} = \\frac{624 + 1}{625} = 1.0\\ \\text{s} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">c</span><span class="mord mathnormal mtight">n</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.0074em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">64</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">40000</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord">625</span><span class="mspace"> </span><span class="mord text"><span class="mord">Hz</span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">o</span><span class="mord mathnormal mtight">u</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.0074em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">625</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">624</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1.0</span><span class="mspace"> </span><span class="mord text"><span class="mord">s</span></span></span></span></span></span><p>即：<strong>必须在 1 秒内喂一次狗</strong>，否则芯片复位。</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">hiwdg.Instance </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> IWDG;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">hiwdg.Init.Prescaler </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> IWDG_PRESCALER_64;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">hiwdg.Init.Reload </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 624</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">HAL_IWDG_Init</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">hiwdg</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 主循环里定期喂狗</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">HAL_IWDG_Refresh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">hiwdg</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p><strong>喂狗位置的原则</strong>：</p><ul><li>✅ 在主循环里喂：主循环能跑到 = 程序整体还在正常流转；</li><li>❌ <strong>不要在定时器中断里喂</strong>：中断可能照常触发，而主任务早就卡死了——这样看门狗形同虚设；</li><li>✅ 更好的做法是<strong>多任务系统里由各任务「报到」，全部报到才喂狗</strong>（事件组实现），这样任何单个任务卡死都能被检测到。</li></ul><p><strong>调试提示</strong>：调试时程序在断点处暂停，看门狗会溢出复位，让人以为是程序有问题。<strong>调试阶段用 <code>__HAL_DBGMCU_FREEZE_IWDG()</code> 让调试时暂停看门狗</strong>。</p></div><h2 id="五、综合项目-把十二章串起来" tabindex="-1">五、综合项目：把十二章串起来 <a class="header-anchor" href="#五、综合项目-把十二章串起来" aria-label="Permalink to &quot;五、综合项目：把十二章串起来&quot;">​</a></h2><p>一个典型的练手项目：<strong>低功耗温湿度记录仪</strong>。需求：每 10 秒采集一次温湿度，显示在 OLED 上，通过串口上报，电池供电要撑半年以上。</p><p><strong>该怎么拆解</strong>：</p><table tabindex="0"><thead><tr><th>环节</th><th>用到的章节</th></tr></thead><tbody><tr><td>选型（F103 够不够：Flash/RAM、外设）</td><td><a href="./overview">01 概览</a></td></tr><tr><td>建工程、CubeMX 配引脚与时钟、点灯验证</td><td><a href="./environment">02 环境</a>、<a href="./clock">04 时钟树</a></td></tr><tr><td>读传感器（I²C）、写寄存器位操作</td><td><a href="./embedded-c">03 嵌入式 C</a>、<a href="./spi-i2c">09 SPI/I²C</a></td></tr><tr><td>按键切换显示页面（外部中断 + 消抖）</td><td><a href="./gpio">05 GPIO</a>、<a href="./interrupt">06 中断</a></td></tr><tr><td>定时唤醒采集（RTC 闹钟 / 定时中断）</td><td><a href="./timer-pwm">07 定时器</a>、本章低功耗</td></tr><tr><td>若传感器是模拟量则走 ADC + DMA</td><td><a href="./adc-dma">10 ADC 与 DMA</a></td></tr><tr><td>串口上报（DMA + 空闲中断 + 帧协议）</td><td><a href="./uart">08 串口</a></td></tr><tr><td>采集/显示/通信拆成三个任务</td><td><a href="./rtos">11 RTOS</a></td></tr><tr><td>10 秒唤醒一次，其余时间 Stop</td><td>本章</td></tr></tbody></table><p><strong>资源与功耗预算</strong>（示例）：</p><ul><li><strong>Flash</strong>：HAL + FreeRTOS + 简单驱动 ≈ 60 KB → 选 128 KB 的 <code>CBT6</code>；</li><li><strong>RAM</strong>：3 个任务栈（各 512 B）+ 队列缓冲 + OLED 显存 1 KB ≈ 4 KB → 20 KB 够用；</li><li><strong>功耗</strong>：每 10 秒唤醒，活跃 5 ms @30 mA，其余 Stop @20 µA → 平均约 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>30</mn><mo>×</mo><mn>0.0005</mn><mo>+</mo><mn>0.02</mn><mo>≈</mo><mn>35</mn><mtext> </mtext><mi>μ</mi><mtext>A</mtext></mrow><annotation encoding="application/x-tex">30 \\times 0.0005 + 0.02 \\approx 35\\ \\mu\\text{A}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">30</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">0.0005</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.02</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord">35</span><span class="mspace"> </span><span class="mord mathnormal">μ</span><span class="mord text"><span class="mord">A</span></span></span></span></span>，200 mAh 可撑约 238 天。</li></ul><p><strong>这个项目的真正难点不是某个外设，而是三点</strong>：① 唤醒后时钟和外设要正确恢复；② I²C 在睡眠/唤醒切换时容易死锁，要有总线恢复代码；③ 功耗要实测（用电流表串在供电回路里），而不是靠算。</p><h2 id="六、易错清单-自检" tabindex="-1">六、易错清单 + 自检 <a class="header-anchor" href="#六、易错清单-自检" aria-label="Permalink to &quot;六、易错清单 + 自检&quot;">​</a></h2><ul><li>[ ] <strong>不用的 GPIO 保持浮空输入</strong> → 漏电吃掉低功耗的收益（配成模拟输入）</li><li>[ ] <strong>在中断里喂看门狗</strong> → 主任务卡死也检测不到</li><li>[ ] <strong>调试时被看门狗复位</strong> → 用 <code>__HAL_DBGMCU_FREEZE_IWDG()</code> 冻结</li><li>[ ] <strong>唤醒后忘了重新配置时钟</strong>（Stop 唤醒后 HSE/PLL 需要重新初始化）</li><li>[ ] <strong>以为 Standby 唤醒后程序会继续</strong> → 它等于复位，RAM 数据全丢（要存备份寄存器）</li><li>[ ] <strong>只优化睡眠电流，却让活跃时间很长</strong> → 收益最大的其实是缩短活跃时间</li><li>[ ] <strong>频繁唤醒</strong>：唤醒开销可能让「多睡」反而更耗电</li><li>[ ] <strong>IWDG 一旦开启停不下来</strong>：低功耗模式下也要考虑喂狗策略</li></ul><p><strong>自检</strong>：200 mAh 电池在 Stop 模式（20 µA）能撑多久？平均电流主要由什么决定？看门狗应该在哪里喂？（答案：约 417 天；活跃时间与活跃电流的乘积（占空比），而非睡眠电流；主循环里，或各任务全部报到后再喂，不能在中断里喂）</p>`,33))])}const x=n(c,[["render",o]]);export{b as __pageData,x as default};
